-- @migracion: particular (no se aplica a todas las bases: ver htdocs/proyectos)
-- =====================================================================
-- Migracion de PRODUCCION Casa Lucho al formato actual
-- Script 06: AJUSTES DE CONFIGURACION
-- 2026-10-31
-- =====================================================================
-- Requiere los scripts 01 a 05. Surge de correr 01 -> 05 sobre
-- ps_gestion_casalucho y comparar sus datos con gestion_multipyme por clave
-- primaria y por clave natural (empresas 0, 1 y 2). Las INSERT salen de la base
-- local; el resto, a mano.
--
-- Que hace (solo configuracion, nada operativo):
--   1) Permisos de Matriz Legal de los perfiles 301-308 de la empresa 2: las
--      funciones de las paginas del modulo 3 (300-399) que local tiene
--      asignadas y produccion no. Solo si el perfil existe en produccion y es
--      de la empresa 2. Ningun usuario de produccion tiene esos perfiles hoy.
--   2) Catalogos de Matriz Legal que produccion tiene vacios: tipos de
--      procedimiento, feriados, opciones del grupo 1 (empresa 2) y la region
--      "Cono Sur" con la empresa 2.
--   3) sindi__obras_sociales: catalogo global (sin empresa) del modulo 6.
--   4) Cuentas 101-108 de la empresa 2 (cajas y bancos): es_caja_banco = 1,
--      como en local (mismo id, codigo y nombre en las dos bases).
--   5) Perfiles base 3 y 4 del modulo 2 (Administrador / Administrativo 1,
--      reemplazados por los perfiles base 201-208): inactivos, como en local.
--   6) Ambiente de produccion de ARCA (conf__integraciones_ambientes 2):
--      activo, como en local. No habilita la facturacion electronica: eso
--      sigue dependiendo de gestion__empresas_parametros.arca_habilitado.
--
-- NO copia, a proposito:
--   - Los permisos de Cobranzas, Medios de Pago, Conceptos Contables y
--     Dashboard Financiero que local asigna a TODOS los perfiles (tambien a
--     Operador, Pedidos y a los de Matriz Legal): en produccion daria acceso a
--     usuarios reales. Se asignan desde Perfiles si hacen falta.
--   - Permisos de perfiles que produccion no tiene (modulos 4 y 5, ML 309-312)
--     ni de los perfiles 5-7 (en produccion son de CEC Patagones).
--   - Lo de las empresas 3, 6 y 7 (cancelaciones de tipos sindicales,
--     autorizaciones de copia, formatos bancarios, impuestos_config_subgrupos).
--   - conf__empresas (CUIT real de Casa Lucho), modulos y nombres de perfiles,
--     usuarios, parametros de IA (clave cifrada), certificados ARCA,
--     numeradores, conf___perfiles_paginas (sin uso en el codigo) y todo lo
--     operativo.
--
-- Reanudable: INSERT IGNORE / NOT EXISTS y UPDATE idempotentes.
--   mysql -u <USUARIO> -p --default-character-set=utf8mb4 <BASE> < 20261031_migracion_casalucho_06_ajustes_configuracion.sql
-- =====================================================================

SET NAMES utf8mb4;
-- Sin USE: la base se indica en la linea de comando.
SET @OLD_FOREIGN_KEY_CHECKS = @@FOREIGN_KEY_CHECKS;
SET FOREIGN_KEY_CHECKS = 0;

START TRANSACTION;

