-- ---------------------------------------------------------------------
-- 4) Cajas y bancos del plan de cuentas de la empresa 2
-- ---------------------------------------------------------------------
UPDATE gestion__cont_cuentas SET es_caja_banco = 1
WHERE empresa_id = 2 AND cont_cuenta_id BETWEEN 101 AND 108 AND codigo LIKE '1.1.01.%' AND es_caja_banco = 0;

-- ---------------------------------------------------------------------
-- 5) Perfiles base viejos del modulo 2
-- ---------------------------------------------------------------------
UPDATE conf__perfiles SET tabla_estado_registro_id = 2
WHERE perfil_id IN (3, 4) AND modulo_id = 2 AND tabla_estado_registro_id <> 2;

-- ---------------------------------------------------------------------
-- 6) Ambiente de produccion de ARCA
-- ---------------------------------------------------------------------
UPDATE conf__integraciones_ambientes SET activo = 1
WHERE integracion_ambiente_id = 2 AND codigo = 'produccion' AND activo = 0;

COMMIT;

SET FOREIGN_KEY_CHECKS = @OLD_FOREIGN_KEY_CHECKS;
